-- Single SQL statement, invoker permissions and RLS. F6 must grant access explicitly.
create function public.get_public_snapshot() returns jsonb
language sql stable security invoker set search_path = ''
as $$
with
snapshot_settings as (
  select r.id,
    r.site_name,
    r.brand_short,
    r.professional_title,
    r.hero_title,
    r.hero_subtitle,
    r.hero_description,
    r.availability_enabled,
    r.availability_text,
    r.location_public,
    (select d.public_url from public.documents d join public.media_assets m on m.id = d.asset_id where d.active and m.visibility = 'public' and exists (select 1 from public.contact_settings where cv_enabled)) as cv_url,
    r.default_seo_title,
    r.default_seo_description,
    case when exists (select 1 from public.media_assets m where m.id = r.default_og_image_asset_id and m.visibility = 'public') then r.default_og_image end as default_og_image,
    case when exists (select 1 from public.media_assets m where m.id = r.default_og_image_asset_id and m.visibility = 'public') then r.default_og_image_asset_id end as default_og_image_asset_id,
    r.about_summary_markdown,
    r.about_profile_markdown,
    r.working_method_markdown,
    case when exists (select 1 from public.media_assets m where m.id = r.about_image_asset_id and m.visibility = 'public') then r.about_image_asset_id end as about_image_asset_id,
    r.canonical_base,
    r.robots_policy,
    r.timezone
  from public.site_settings r where true
),
snapshot_contact as (
  select r.id,
    case when r.email_visible then r.email end as email,
    case when r.whatsapp_visible then r.whatsapp_number end as whatsapp_number,
    case when r.whatsapp_visible then r.whatsapp_default_message end as whatsapp_default_message,
    r.cta_title,
    r.cta_description,
    r.form_enabled,
    r.cv_enabled,
    r.email_visible,
    r.whatsapp_visible,
    case when r.whatsapp_visible then r.whatsapp_cta_label end as whatsapp_cta_label
  from public.contact_settings r where true
),
snapshot_social_links as (
  select r.id,
    r.platform,
    r.label,
    r.url,
    r.icon,
    r.sort_order,
    r.visible
  from public.social_links r where r.visible
),
snapshot_projects as (
  select r.id,
    r.title,
    r.slug,
    r.subtitle,
    r.summary,
    r.problem,
    r.objective,
    r.solution,
    r.architecture,
    r.challenges,
    r.learnings,
    r.role,
    r.year,
    r.status,
    case when exists (select 1 from public.media_assets m where m.id = r.featured_image_asset_id and m.visibility = 'public') then r.featured_image_url end as featured_image_url,
    case when exists (select 1 from public.media_assets m where m.id = r.cover_image_asset_id and m.visibility = 'public') then r.cover_image_url end as cover_image_url,
    r.github_url,
    r.demo_url,
    r.documentation_url,
    r.featured,
    r.published,
    r.seo_title,
    r.seo_description,
    case when exists (select 1 from public.media_assets m where m.id = r.og_image_asset_id and m.visibility = 'public') then r.og_image_url end as og_image_url,
    r.published_at,
    r.canonical_url,
    r.robots_policy,
    r.before_markdown,
    r.after_markdown,
    r.sort_order,
    case when exists (select 1 from public.media_assets m where m.id = r.featured_image_asset_id and m.visibility = 'public') then r.featured_image_asset_id end as featured_image_asset_id,
    case when exists (select 1 from public.media_assets m where m.id = r.cover_image_asset_id and m.visibility = 'public') then r.cover_image_asset_id end as cover_image_asset_id,
    case when exists (select 1 from public.media_assets m where m.id = r.og_image_asset_id and m.visibility = 'public') then r.og_image_asset_id end as og_image_asset_id
  from public.projects r where r.published and r.status <> 'archived' and r.published_at <= statement_timestamp()
),
snapshot_posts as (
  select r.id,
    r.title,
    r.slug,
    r.excerpt,
    r.content_markdown,
    case when exists (select 1 from public.media_assets m where m.id = r.featured_image_asset_id and m.visibility = 'public') then r.featured_image_url end as featured_image_url,
    r.status,
    r.featured,
    r.reading_time,
    r.seo_title,
    r.seo_description,
    case when exists (select 1 from public.media_assets m where m.id = r.og_image_asset_id and m.visibility = 'public') then r.og_image_url end as og_image_url,
    r.published_at,
    r.canonical_url,
    r.robots_policy,
    r.popular_rank,
    case when exists (select 1 from public.media_assets m where m.id = r.featured_image_asset_id and m.visibility = 'public') then r.featured_image_asset_id end as featured_image_asset_id,
    case when exists (select 1 from public.media_assets m where m.id = r.og_image_asset_id and m.visibility = 'public') then r.og_image_asset_id end as og_image_asset_id
